local FlourShovelMaker = {}
local PRODUCTS = {
    iron_flourshovel = { name = "Železni lopata za moko", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni lopata za moko za pekarno." },
    bronze_flourshovel = { name = "Bronast lopata za moko", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast lopata za moko za pekarno." },
    silver_flourshovel = { name = "Srebrn lopata za moko", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn lopata za moko za pekarno." },
    gilded_flourshovel = { name = "Pozlačen lopata za moko", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen lopata za moko za pekarno." },
    jewel_set_flourshovel = { name = "Draguljast lopata za moko", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast lopata za moko za pekarno." },
    royal_sovereign_flourshovel = { name = "Kraljevski suveren lopata za moko", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren lopata za moko z biseri za krono." },
}
local BUILDINGS = {
    flourshovel_workshop = { name = "Flourshovel delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    flourshovel_house = { name = "Flourshovel hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_flourshovel_atelier = { name = "Mojstrski flourshovel atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_flourshovel_palace = { name = "Suverena flourshovel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
FlourShovelMaker.ironStock = 14; FlourShovelMaker.bronzeStock = 12; FlourShovelMaker.woodStock = 16; FlourShovelMaker.leatherStock = 8; FlourShovelMaker.silverStock = 8; FlourShovelMaker.goldStock = 6; FlourShovelMaker.jewelStock = 4; FlourShovelMaker.pearlStock = 4
FlourShovelMaker.productStock = {}; FlourShovelMaker.buildings = {}; FlourShovelMaker.maker = nil; FlourShovelMaker.activeMaking = {}; FlourShovelMaker.totalProducts = 0; FlourShovelMaker.dayTimer = 0
function FlourShovelMaker.init() FlourShovelMaker.ironStock=14; FlourShovelMaker.bronzeStock=12; FlourShovelMaker.woodStock=16; FlourShovelMaker.leatherStock=8; FlourShovelMaker.silverStock=8; FlourShovelMaker.goldStock=6; FlourShovelMaker.jewelStock=4; FlourShovelMaker.pearlStock=4; FlourShovelMaker.productStock={}; FlourShovelMaker.buildings={}; FlourShovelMaker.maker=nil; FlourShovelMaker.activeMaking={}; FlourShovelMaker.totalProducts=0; FlourShovelMaker.dayTimer=0; print("[FlourShovelMaker] Royal Flour Shovel Maker System initialized (6 products, 4 buildings)") end
function FlourShovelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FlourShovelMaker.maker={name=n or ("Mokar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mokar najet: %s (spretnost: %d)",FlourShovelMaker.maker.name,s),"success") end; return true end
function FlourShovelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FlourShovelMaker.build(id) local ok,e=FlourShovelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FlourShovelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FlourShovelMaker.getQualityBonus() local b=0; for _,bd in ipairs(FlourShovelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FlourShovelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FlourShovelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FlourShovelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FlourShovelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FlourShovelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FlourShovelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FlourShovelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FlourShovelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FlourShovelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FlourShovelMaker.buildings==0 then return false,"Potrebna mokna delavnica" end; if not FlourShovelMaker.maker then return false,"Potreben mokar" end; return true end
function FlourShovelMaker.make(pt,qty) qty=qty or 1; local ok,e=FlourShovelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FlourShovelMaker.ironStock=FlourShovelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FlourShovelMaker.bronzeStock=FlourShovelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FlourShovelMaker.woodStock=FlourShovelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FlourShovelMaker.leatherStock=FlourShovelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FlourShovelMaker.silverStock=FlourShovelMaker.silverStock-d.silverCost*qty end; if d.goldCost then FlourShovelMaker.goldStock=FlourShovelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FlourShovelMaker.jewelStock=FlourShovelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FlourShovelMaker.pearlStock=FlourShovelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FlourShovelMaker.maker then t=math.max(1,t-math.floor(FlourShovelMaker.maker.skill/13)) end; table.insert(FlourShovelMaker.activeMaking,{id="flourshovel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FlourShovelMaker.completeMaking(m) local q=1.0+(FlourShovelMaker.getQualityBonus()/100); if FlourShovelMaker.maker then q=q+(FlourShovelMaker.maker.skill/140) end; q=math.min(2.5,q); FlourShovelMaker.productStock[m.productType]=(FlourShovelMaker.productStock[m.productType] or 0)+m.quantity; FlourShovelMaker.totalProducts=FlourShovelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FlourShovelMaker.maker then FlourShovelMaker.maker.itemsMade=FlourShovelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FlourShovelMaker.maker.skill=math.min(100,FlourShovelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopata izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"flourshovel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function FlourShovelMaker.update(dt) if not _G.state then return end; FlourShovelMaker.dayTimer=FlourShovelMaker.dayTimer+dt; if FlourShovelMaker.dayTimer>=30 then FlourShovelMaker.dayTimer=0; for i=#FlourShovelMaker.activeMaking,1,-1 do local m=FlourShovelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FlourShovelMaker.completeMaking(m); table.remove(FlourShovelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FlourShovelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FlourShovelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FlourShovelMaker.getStats() return {ironStock=FlourShovelMaker.ironStock,bronzeStock=FlourShovelMaker.bronzeStock,woodStock=FlourShovelMaker.woodStock,leatherStock=FlourShovelMaker.leatherStock,silverStock=FlourShovelMaker.silverStock,goldStock=FlourShovelMaker.goldStock,jewelStock=FlourShovelMaker.jewelStock,pearlStock=FlourShovelMaker.pearlStock,productStock=FlourShovelMaker.productStock,numBuildings=#FlourShovelMaker.buildings,hasMaker=FlourShovelMaker.maker~=nil,makerName=FlourShovelMaker.maker and FlourShovelMaker.maker.name or "—",makerSkill=FlourShovelMaker.maker and FlourShovelMaker.maker.skill or 0,activeMaking=#FlourShovelMaker.activeMaking,totalProducts=FlourShovelMaker.totalProducts} end
return FlourShovelMaker
